"use client";

import { useState } from "react";
import { Search, Bell, Menu } from "lucide-react";
import Sidebar from "./Sidebar";
import { useAuth } from "../../../context/AuthContext";

export default function MobileShell({
  navItems = [],
  pageMap = {},
  defaultPage = "",
  user: userProp,
  onLogout,
  greeting = "",
}) {
  const auth = useAuth();

  // Read real user from AuthContext, fall back to prop
  const user = userProp ?? {
    name: auth?.user?.name ?? "User",
    email: auth?.user?.email ?? "",
    initials: auth?.user?.initials ?? "U",
  };

  // Build greeting dynamically if not passed as prop
  const displayGreeting =
    greeting || `Hi ${user.name?.split(" ")[0] ?? "there"} 👋,`;

  const [activePage, setActivePage] = useState(defaultPage || navItems[0]?.key);
  const [drawerOpen, setDrawerOpen] = useState(false);

  const PageComponent =
    pageMap[activePage] ??
    (() => (
      <div className="flex-1 flex items-center justify-center text-gray-400 text-sm">
        {activePage} — coming soon
      </div>
    ));

  const handleNav = (href) => {
    // navItems use key as href for mobile shell
    const item = navItems.find((n) => n.href === href || n.key === href);
    if (item) setActivePage(item.key ?? item.href);
    setDrawerOpen(false);
  };

  // Map mobile navItems (key-based) to Sidebar format (href-based)
  const sidebarNavItems = navItems.map((n) => ({
    label: n.label,
    icon: n.icon,
    href: n.key ?? n.href,
  }));

  // Find active label for Sidebar's activeItem prop
  const activeLabel =
    navItems.find((n) => (n.key ?? n.href) === activePage)?.label ?? "";

  return (
    <div className="min-h-screen bg-gray-200 flex items-start justify-center">
      <div className="relative w-full md:w-120 h-screen md:min-h-0 md:rounded-3xl md:shadow-2xl bg-[#f5f5f5] overflow-hidden flex flex-col md:max-h-225">
        {/* ── Top bar ─────────────────────────────────────────── */}
        <div className="flex items-center justify-between px-5 pt-4 pb-3 bg-[#f5f5f5] shrink-0">
          <button
            onClick={() => setDrawerOpen(true)}
            className="p-1 text-gray-600 hover:text-gray-900 transition-colors"
          >
            <Menu size={22} />
          </button>
          <div className="flex items-center gap-4">
            <button className="text-gray-500 hover:text-gray-700">
              <Search size={20} />
            </button>
            <button className="relative text-gray-500 hover:text-gray-700">
              <Bell size={20} />
              <span className="absolute -top-0.5 -right-0.5 w-2 h-2 rounded-full bg-red-500" />
            </button>
          </div>
        </div>

        {/* ── Page content ────────────────────────────────────── */}
        <div className="flex-1 overflow-y-auto">
          <PageComponent greeting={displayGreeting} onNavigate={handleNav} />
        </div>

        {/* ── Drawer — reuses desktop Sidebar ─────────────────── */}
        {drawerOpen && (
          <>
            {/* Backdrop */}
            <div
              className="absolute inset-0 bg-black/30 z-20"
              onClick={() => setDrawerOpen(false)}
            />
            {/* Sidebar rendered inside drawer */}
            <div className="absolute top-0 left-0 h-full z-30">
              <Sidebar
                activeItem={activeLabel}
                navItems={sidebarNavItems}
                user={user}
                onLogout={onLogout}
                onNavClick={(href) => handleNav(href)}
              />
            </div>
          </>
        )}
      </div>
    </div>
  );
}
